import { useEffect, useState } from 'react';
import { useAuth } from '../../context/AuthContext';
import { getTeacherSubmissions, gradeSubmission } from '../../api';
import { Badge, Card, SectionTitle, Spinner } from '../../components/UI';

export default function TeacherSubmissions() {
  const { user } = useAuth();
  const [submissions, setSubmissions] = useState([]);
  const [loading,     setLoading]     = useState(true);
  const [grading,     setGrading]     = useState(null); // submission being graded
  const [form,        setForm]        = useState({ marks_obtained: '', grade: 'B', feedback: '' });
  const [saving,      setSaving]      = useState(false);

  useEffect(() => {
    getTeacherSubmissions(user.id).then(r => setSubmissions(r.data)).finally(() => setLoading(false));
  }, [user.id]);

  const openGrade = (s) => {
    setGrading(s);
    setForm({ marks_obtained: s.marks_obtained || '', grade: s.grade || 'B', feedback: s.feedback || '' });
  };

  const handleSave = async () => {
    setSaving(true);
    await gradeSubmission({
      submission_id: grading.submission_id,
      student_id:    grading.student_id,
      assignment_id: grading.assignment_id,
      total_marks:   grading.total_marks,
      ...form,
    });
    setSubmissions(prev => prev.map(s =>
      s.submission_id === grading.submission_id ? { ...s, ...form } : s
    ));
    setGrading(null);
    setSaving(false);
  };

  if (loading) return <Spinner />;

  return (
    <div className="p-6 max-w-4xl">
      <div className="mb-6">
        <h1 className="text-xl font-medium text-gray-900">Submissions</h1>
        <p className="text-sm text-gray-400 mt-0.5">{submissions.filter(s => !s.grade).length} pending grading</p>
      </div>

      <Card>
        <SectionTitle>All submissions</SectionTitle>
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead>
              <tr className="text-xs text-gray-400 border-b border-gray-100">
                <th className="text-left pb-2 font-medium">Student</th>
                <th className="text-left pb-2 font-medium">Assignment</th>
                <th className="text-left pb-2 font-medium">Course</th>
                <th className="text-left pb-2 font-medium">Submitted</th>
                <th className="text-left pb-2 font-medium">Status</th>
                <th className="text-left pb-2 font-medium">Grade</th>
                <th className="text-left pb-2 font-medium"></th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-50">
              {submissions.map(s => (
                <tr key={s.submission_id}>
                  <td className="py-2.5 font-medium text-gray-800">{s.student_name}</td>
                  <td className="py-2.5 text-gray-600 max-w-[160px] truncate">{s.assignment_title}</td>
                  <td className="py-2.5 font-mono text-xs text-brand-600">{s.course_code}</td>
                  <td className="py-2.5 text-gray-400 text-xs">
                    {s.submitted_at ? new Date(s.submitted_at).toLocaleDateString() : '—'}
                  </td>
                  <td className="py-2.5">
                    <Badge
                      label={s.submission_status || 'Pending'}
                      variant={s.submission_status === 'Submitted' ? 'green' : s.submission_status === 'Late' ? 'red' : 'amber'}
                    />
                  </td>
                  <td className="py-2.5">
                    {s.grade
                      ? <span className="text-sm font-medium text-gray-700">{s.grade} · {s.marks_obtained}/{s.total_marks}</span>
                      : <span className="text-xs text-gray-400">Not graded</span>
                    }
                  </td>
                  <td className="py-2.5">
                    <button
                      onClick={() => openGrade(s)}
                      className="text-xs text-brand-600 hover:text-brand-800 font-medium"
                    >
                      {s.grade ? 'Edit' : 'Grade'}
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </Card>

      {/* Grade modal */}
      {grading && (
        <div className="fixed inset-0 bg-black/20 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-2xl p-6 w-full max-w-md shadow-lg">
            <h2 className="text-base font-medium text-gray-900 mb-1">Grade submission</h2>
            <p className="text-sm text-gray-400 mb-4">{grading.student_name} · {grading.assignment_title}</p>

            <div className="flex flex-col gap-3">
              <div>
                <label className="text-xs text-gray-500 mb-1 block">Marks obtained (out of {grading.total_marks})</label>
                <input
                  type="number" min="0" max={grading.total_marks}
                  value={form.marks_obtained}
                  onChange={e => setForm(f => ({ ...f, marks_obtained: e.target.value }))}
                  className="w-full border border-gray-200 rounded-xl px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-brand-200"
                />
              </div>
              <div>
                <label className="text-xs text-gray-500 mb-1 block">Grade</label>
                <select
                  value={form.grade}
                  onChange={e => setForm(f => ({ ...f, grade: e.target.value }))}
                  className="w-full border border-gray-200 rounded-xl px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-brand-200 bg-white"
                >
                  {['A','B','C','D','F'].map(g => <option key={g}>{g}</option>)}
                </select>
              </div>
              <div>
                <label className="text-xs text-gray-500 mb-1 block">Feedback</label>
                <textarea
                  rows={3}
                  value={form.feedback}
                  onChange={e => setForm(f => ({ ...f, feedback: e.target.value }))}
                  className="w-full border border-gray-200 rounded-xl px-3 py-2 text-sm resize-none focus:outline-none focus:ring-2 focus:ring-brand-200"
                  placeholder="Optional feedback for the student..."
                />
              </div>
            </div>

            <div className="flex gap-2 mt-5">
              <button
                onClick={() => setGrading(null)}
                className="flex-1 py-2 text-sm text-gray-500 border border-gray-200 rounded-xl hover:bg-gray-50"
              >
                Cancel
              </button>
              <button
                onClick={handleSave}
                disabled={saving || !form.marks_obtained}
                className="flex-1 py-2 text-sm text-white bg-brand-600 rounded-xl hover:bg-brand-800 disabled:opacity-40"
              >
                {saving ? 'Saving…' : 'Save grade'}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
